1	// PhishSense game logic (runs in the browser)
2	
3	const ROUNDS = 5;        // rounds per mode
4	const TO_PASS = 4;       // correct answers needed for the badge
5	const PER_CORRECT = 100; // points per correct answer
6	const BADGES = { easy: "🐟 Minnow", medium: "🎣 Angler", hard: "⚓ Captain" };
7	const ALL_MODES = ["easy", "medium", "hard"];
8	const MISSIONS = {
9	  easy: "Warm-up shift. These scams are obvious: watch for typos, surprise prizes, and ALL CAPS urgency.",
10	  medium: "Scammers are getting smarter. Check every sender address and phone number against the real ones above.",
11	  hard: "Expert level. Some scams look perfect, and some real emails look scary. Read every detail before you decide.",
12	};
13	
14	// The real addresses players check every message against.
15	const TRUSTED = [
16	  { name: "Bayline Energy", note: "your company", domain: "bayline-energy.com", phone: "(404) 555-0100" },
17	  { name: "NewsNow", domain: "newsnow.com" },
18	  { name: "ConnectPro", domain: "connectpro.com" },
19	  { name: "TechHub", domain: "techhub.com" },
20	];
21	
22	let mode, round, correct, current, seen;
23	let results;  // one entry per round: true (correct) or false (wrong)
24	let streak;   // correct answers in a row, resets on a wrong answer
25	let missed;   // every red flag from the rounds the player got wrong
26	
27	const $ = (id) => document.getElementById(id);
28	const show = (id) => {
29	  ["start-screen", "mission-screen", "play-screen", "end-screen"].forEach((s) => $(s).classList.add("hidden"));
30	  $(id).classList.remove("hidden");
31	};
32	const esc = (t) => String(t ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
33	
34	// Players who ask for less motion get the same game with the animations off.
35	const calmMode = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;
36	
37	// ---------- Talking to the backend ----------
38	// Practice mode: if the backend isn't running (opened as a file, Live Server,
39	// or a static host like Vercel), the game uses mock-data.js instead.
40	let OFFLINE = location.protocol === "file:";
41	
42	async function checkBackend() {
43	  if (OFFLINE) return;
44	  try {
45	    const r = await fetch("/api/leaderboard");
46	    if (!r.ok) throw new Error("no backend");
47	    await r.json();
48	  } catch (e) {
49	    OFFLINE = true;
50	  }
51	}
52	
53	async function apiGetScenario(mode, seen) {
54	  if (OFFLINE) {
55	    const pool = MOCK_SCENARIOS.filter((s) => s.difficulty === mode && !seen.includes(s.scenario_id));
56	    const s = pool[Math.floor(Math.random() * pool.length)];
57	    return { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
58	  }
59	  return fetch(`/api/scenario?mode=${mode}&seen=${seen.join(",")}`).then((r) => r.json());
60	}
61	
62	async function apiAnswer(scenario_id, guess) {
63	  if (OFFLINE) {
64	    const s = MOCK_SCENARIOS.find((x) => x.scenario_id === scenario_id);
65	    return { correct: guess === s.game_answer, game_answer: s.game_answer, red_flags: s.red_flags, explanation: s.explanation };
66	  }
67	  return fetch("/api/answer", {
68	    method: "POST",
69	    headers: { "Content-Type": "application/json" },
70	    body: JSON.stringify({ scenario_id, guess }),
71	  }).then((r) => r.json());
72	}
73	
74	async function apiSaveScore(username, points, badge) {
75	  if (OFFLINE) {
76	    const board = JSON.parse(localStorage.getItem("ps-board") || "{}");
77	    const p = board[username] || { username, total_score: 0, badges: [] };
78	    p.total_score += points;
79	    if (badge && !p.badges.includes(badge)) p.badges.push(badge);
80	    board[username] = p;
81	    try { localStorage.setItem("ps-board", JSON.stringify(board)); } catch (e) {}
82	    return p;
83	  }
84	  return fetch("/api/score", {
85	    method: "POST",
86	    headers: { "Content-Type": "application/json" },
87	    body: JSON.stringify({ username, points, badge }),
88	  }).then((r) => r.json());
89	}
90	
91	async function apiLeaderboard() {
92	  if (OFFLINE) {
93	    let board = {};
94	    try { board = JSON.parse(localStorage.getItem("ps-board") || "{}"); } catch (e) {}
95	    return Object.values(board)
96	      .sort((a, b) => b.badges.length - a.badges.length || b.total_score - a.total_score)
97	      .slice(0, 10);
98	  }
99	  return fetch("/api/leaderboard").then((r) => r.json());
100	}
101	
102	// ---------- Trusted contacts ----------
103	// One list, shown on the mission briefing and in the panel during play.
104	function contactsHTML() {
105	  const rows = TRUSTED.map((c) => `<tr>
106	      <th scope="row">${esc(c.name)}${c.note ? `<small>${esc(c.note)}</small>` : ""}</th>
107	      <td><span class="contact-domain">${esc(c.domain)}</span>${c.phone ? `<span class="contact-phone">${esc(c.phone)}</span>` : ""}</td>
108	    </tr>`).join("");
109	  return `<table class="contacts-table">
110	      <thead><tr><th scope="col">Company</th><th scope="col">Real website &amp; phone</th></tr></thead>
111	      <tbody>${rows}</tbody>
112	    </table>
113	    <p class="contacts-tip">Scammers use names you trust with addresses that don't match. Always compare.</p>`;
114	}
115	document.querySelectorAll(".contacts-list").forEach((el) => (el.innerHTML = contactsHTML()));
116	
117	function setContactsOpen(open) {
118	  $("contacts-panel").classList.toggle("hidden", !open);
119	  $("btn-contacts").setAttribute("aria-expanded", String(open));
120	  $("btn-contacts").classList.toggle("open", open);
121	}
122	$("btn-contacts").addEventListener("click", () =>
123	  setContactsOpen($("contacts-panel").classList.contains("hidden")));
124	document.addEventListener("keydown", (e) => {
125	  if (e.key === "Escape" && !$("contacts-panel").classList.contains("hidden")) {
126	    setContactsOpen(false);
127	    $("btn-contacts").focus();
128	  }
129	});
130	
131	// ---------- Start: pick a difficulty, then see the mission ----------
132	document.querySelectorAll(".mode").forEach((btn) =>
133	  btn.addEventListener("click", () => {
134	    if (!$("username").value.trim()) return $("username").focus();
135	    mode = btn.dataset.mode;
136	    const label = mode.charAt(0).toUpperCase() + mode.slice(1);
137	    $("mission-mode").textContent = `${label} mode · ${BADGES[mode]} badge`;
138	    $("mission-tip").textContent = MISSIONS[mode];
139	    show("mission-screen");
140	  })
141	);
142	
143	$("btn-back").addEventListener("click", () => show("start-screen"));
144	
145	$("btn-start").addEventListener("click", () => {
146	  round = 0;
147	  correct = 0;
148	  seen = [];
149	  results = [];
150	  streak = 0;
151	  missed = [];
152	  $("recap").classList.add("hidden");
153	  $("badge-reveal").classList.add("hidden");
154	  $("confetti").innerHTML = "";
155	  setContactsOpen(false);
156	  show("play-screen");
157	  nextRound();
158	});
159	
160	// ---------- Progress dots + streak ----------
161	function renderDots() {
162	  let html = "";
163	  for (let i = 0; i < ROUNDS; i++) {
164	    let cls = "";
165	    if (results[i] === true) cls = "correct";
166	    else if (results[i] === false) cls = "wrong";
167	    else if (i === round - 1) cls = "current";
168	    html += `<span class="dot ${cls}"></span>`;
169	  }
170	  $("dots").innerHTML = html;
171	  $("dots").setAttribute("aria-label", `Round ${Math.min(round, ROUNDS)} of ${ROUNDS}, ${correct} correct`);
172	}
173	
174	function renderStreak() {
175	  $("streak").textContent =
176	    streak >= 2 ? `🔥 ${streak} in a row` : streak === 1 ? "🔥 1 correct" : "";
177	}
178	
179	// ---------- Play ----------
180	async function nextRound() {
181	  await ready;
182	  round++;
183	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
184	  $("result").classList.add("hidden");
185	  $("btn-next").classList.add("hidden");
186	  $("btn-phish").disabled = $("btn-legit").disabled = true;
187	  $("message").className = "card";   // clears the glow or shake from the last round
188	  $("pop-layer").innerHTML = "";
189	  hidePeek();
190	  renderDots();
191	  renderStreak();
192	  $("message").innerHTML = `<p class="loading">Loading message...</p>`;
193	
194	  current = await apiGetScenario(mode, seen);
195	  seen.push(current.scenario_id);
196	  $("message").innerHTML = renderMessage(current);
197	  $("btn-phish").disabled = $("btn-legit").disabled = false;
198	}
199	
200	// A steady clock time per scenario, so the inbox and phone look real
201	// without the time jumping around every time you re-read a message.
202	function clockFor(s) {
203	  const id = Math.abs(Number(s.scenario_id) || 0);
204	  const hour24 = 8 + ((id * 3) % 9);          // 8 AM to 4 PM
205	  const minute = String((id * 17) % 60).padStart(2, "0");
206	  const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12;
207	  return { short: `${hour12}:${minute}`, long: `${hour12}:${minute} ${hour24 < 12 ? "AM" : "PM"}` };
208	}
209	
210	const initialOf = (sender) => {
211	  const m = String(sender || "").match(/[a-z]/i);
212	  return m ? m[0].toUpperCase() : "?";
213	};
214	
215	// ---------- Hover to inspect links ----------
216	// Emails hide the real address behind friendly text, the way real phishing
217	// does. Hovering (or tapping) shows where the link really goes. The link is a
218	// plain button, so it can never open anything.
219	const LINK_LABELS = [
220	  [/\.exe|download|update/i, "Download the update"],
221	  [/claim|winner|prize|reward/i, "Claim your reward"],
222	  [/sign-?in|log-?in/i, "Sign in to your account"],
223	  [/verify/i, "Verify your account"],
224	  [/confirm/i, "Confirm now"],
225	  [/billing|invoice|payment/i, "View billing details"],
226	  [/video|watch/i, "Watch now"],
227	  [/story|news|article/i, "Read the full story"],
228	];
229	
230	function parseLink(raw) {
231	  const text = String(raw || "").trim();
232	  try {
233	    const u = new URL(/^[a-z]+:\/\//i.test(text) ? text : `http://${text}`);
234	    const host = u.hostname;
235	    const parts = host.split(".");
236	    const domain = parts.length > 2 ? parts.slice(-2).join(".") : host;
237	    return {
238	      scheme: `${u.protocol}//`,
239	      sub: host.slice(0, host.length - domain.length), // e.g. "newsnow.com."
240	      domain,                                          // the site you really land on
241	      rest: u.pathname === "/" && !u.search ? "" : u.pathname + u.search,
242	    };
243	  } catch (e) {
244	    return { scheme: "", sub: "", domain: text, rest: "" };
245	  }
246	}
247	
248	function linkLabel(s) {
249	  if (s.link_text) return s.link_text;
250	  const { rest } = parseLink(s.link);
251	  const hit = LINK_LABELS.find(([re]) => re.test(rest)) || LINK_LABELS.find(([re]) => re.test(s.link));
252	  return hit ? hit[1] : "Open link";
253	}
254	
255	function renderLink(s) {
256	  if (!s.link) return "";
257	  const hint = `<span class="link-hint"><span class="hint-hover">Hover</span><span class="hint-tap">Tap</span> to inspect</span>`;
258	  if (s.channel === "sms") {
259	    // Texts show the raw address, but tapping it still previews the real site.
260	    return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">${esc(s.link)}</button>${hint}</p>`;
261	  }
262	  return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">🔗 ${esc(linkLabel(s))}</button>${hint}</p>`;
263	}
264	
265	const peek = document.createElement("div");
266	peek.id = "link-peek";
267	peek.className = "link-peek";
268	peek.setAttribute("role", "tooltip");
269	peek.hidden = true;
270	document.body.appendChild(peek);
271	
272	let peekFor = null;     // the link the popup belongs to
273	let peekPinned = false; // true after a tap or click, so it stays open
274	
275	function showPeek(chip) {
276	  const p = parseLink(chip.dataset.href);
277	  peek.innerHTML = `
278	    <p class="peek-title">🔍 This link really goes to:</p>
279	    <p class="peek-url">${esc(p.scheme)}${p.sub ? `<span class="peek-sub">${esc(p.sub)}</span>` : ""}<b class="peek-domain">${esc(p.domain)}</b>${esc(p.rest)}</p>
280	    <p class="peek-tip">The real site is the last part of the address, right before the first /</p>`;
281	  peek.hidden = false;
282	  if (peekFor && peekFor !== chip) peekFor.removeAttribute("aria-describedby");
283	  peekFor = chip;
284	  chip.setAttribute("aria-describedby", "link-peek");
285	  placePeek();
286	}
287	
288	function hidePeek() {
289	  peek.hidden = true;
290	  peekPinned = false;
291	  if (peekFor) peekFor.removeAttribute("aria-describedby");
292	  peekFor = null;
293	}
294	
295	// Always open ABOVE the link, so it never covers the Phish / Legit buttons
296	// below the message. If the link is too close to the top of the screen,
297	// scroll up just enough to make room.
298	function placePeek() {
299	  if (!peekFor || peek.hidden) return;
300	  if (!document.body.contains(peekFor)) return hidePeek();
301	  const gap = 8, edge = 12;
302	  const w = peek.offsetWidth, h = peek.offsetHeight;
303	  let r = peekFor.getBoundingClientRect();
304	  const short = edge - (r.top - gap - h);
305	  if (short > 0 && window.scrollY > 0) {
306	    window.scrollBy(0, -Math.min(short, window.scrollY));
307	    r = peekFor.getBoundingClientRect();
308	  }
309	  const top = Math.max(edge, r.top - gap - h);
310	  const left = Math.min(Math.max(edge, r.left), window.innerWidth - w - edge);
311	  peek.style.top = `${top}px`;
312	  peek.style.left = `${Math.max(edge, left)}px`;
313	}
314	
315	const chipFrom = (e) => e.target.closest?.(".link-chip");
316	
317	document.addEventListener("mouseover", (e) => {
318	  const chip = chipFrom(e);
319	  if (chip && !peekPinned) showPeek(chip);
320	});
321	document.addEventListener("mouseout", (e) => {
322	  const chip = chipFrom(e);
323	  if (chip && !peekPinned && !chip.contains(e.relatedTarget)) hidePeek();
324	});
325	document.addEventListener("focusin", (e) => {
326	  const chip = chipFrom(e);
327	  if (chip) showPeek(chip);
328	});
329	document.addEventListener("focusout", (e) => {
330	  if (chipFrom(e) && !peekPinned) hidePeek();
331	});
332	document.addEventListener("click", (e) => {
333	  const chip = chipFrom(e);
334	  if (chip) {
335	    e.preventDefault();
336	    if (peekPinned && peekFor === chip) return hidePeek();
337	    showPeek(chip);
338	    peekPinned = true;
339	  } else if (peekPinned && !peek.contains(e.target)) {
340	    hidePeek();
341	  }
342	});
343	document.addEventListener("keydown", (e) => { if (e.key === "Escape") hidePeek(); });
344	window.addEventListener("scroll", placePeek, { passive: true });
345	window.addEventListener("resize", placePeek);
346	
347	function renderMessage(s) {
348	  const link = renderLink(s);
349	  const clock = clockFor(s);
350	
351	  if (s.channel === "sms") {
352	    return `<div class="sms">
353	      <div class="status-bar">
354	        <span class="sb-time">${esc(clock.short)}</span>
355	        <span class="sb-right">
356	          <span class="signal" aria-hidden="true"><i></i><i></i><i></i><i></i></span>
357	          <span class="battery" aria-hidden="true"><span class="bat-fill"></span></span>
358	        </span>
359	      </div>
360	      <p class="label">💬 Text message from <b>${esc(s.sender)}</b></p>
361	      <p class="bubble">${esc(s.body)}</p>${link}</div>`;
362	  }
363	
364	  return `<div class="email">
365	    <div class="email-head">
366	      <div class="avatar" aria-hidden="true">${esc(initialOf(s.sender))}</div>
367	      <div class="email-who">
368	        <p class="from"><b>From:</b> ${esc(s.sender)}</p>
369	        <p class="subject">${esc(s.subject || "(no subject)")}</p>
370	      </div>
371	      <p class="email-time">${esc(clock.long)}</p>
372	    </div>
373	    <p class="body">${esc(s.body)}</p>${link}
374	    <div class="email-actions">
375	      <button type="button" disabled>↩ Reply</button>
376	      <button type="button" disabled>↪ Forward</button>
377	    </div>
378	  </div>`;
379	}
380	
381	// Red flags arrive as one string with semicolons between them.
382	function flagList(red_flags) {
383	  const parts = Array.isArray(red_flags) ? red_flags : String(red_flags || "").split(";");
384	  return parts.map((f) => String(f).trim()).filter(Boolean);
385	}
386	
387	function floatScore(text) {
388	  if (calmMode()) return;
389	  const bit = document.createElement("span");
390	  bit.className = "pop-score";
391	  bit.textContent = text;
392	  $("pop-layer").appendChild(bit);
393	  setTimeout(() => bit.remove(), 1500);
394	}
395	
396	async function answer(guess) {
397	  $("btn-phish").disabled = $("btn-legit").disabled = true;
398	  const r = await apiAnswer(current.scenario_id, guess);
399	
400	  results[round - 1] = !!r.correct;
401	  if (r.correct) {
402	    correct++;
403	    streak++;
404	    $("message").classList.add("is-correct");
405	    floatScore(`+${PER_CORRECT}`);
406	  } else {
407	    streak = 0;
408	    $("message").classList.add("is-wrong");
409	    flagList(r.red_flags).forEach((f) => missed.push(f));
410	  }
411	  renderDots();
412	  renderStreak();
413	
414	  const flags = r.red_flags
415	    ? `<p><b>Red flags:</b></p><ul>${flagList(r.red_flags).map((f) => `<li>${esc(f)}</li>`).join("")}</ul>`
416	    : "";
417	  const went = current.link
418	    ? `<p class="link-reveal">🔍 That link really went to <b>${esc(parseLink(current.link).domain)}</b></p>`
419	    : "";
420	  $("result").innerHTML = `
421	    <h3>${r.correct ? "✅ Correct!" : "❌ Not quite."} This one was <b>${r.game_answer}</b>.</h3>
422	    ${flags}<p>${esc(r.explanation)}</p>${went}`;
423	  $("result").className = `card ${r.correct ? "good" : "bad"}`;
424	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
425	  $("btn-next").textContent = round < ROUNDS ? "Next" : "See results";
426	  $("btn-next").classList.remove("hidden");
427	}
428	
429	$("btn-phish").addEventListener("click", () => answer("Phish"));
430	$("btn-legit").addEventListener("click", () => answer("Legit"));
431	$("btn-next").addEventListener("click", () => (round < ROUNDS ? nextRound() : finish()));
432	
433	// ---------- Badge reveal ----------
434	const CONFETTI_COLORS = ["#2de0c4", "#3ddc84", "#ffd166", "#ff5d6c", "#8ecae6", "#ffffff"];
435	
436	// Replays a CSS animation that has already run once this session.
437	function replayAnimation(el) {
438	  el.style.animation = "none";
439	  void el.offsetWidth;
440	  el.style.animation = "";
441	}
442	
443	function burstConfetti() {
444	  const layer = $("confetti");
445	  layer.innerHTML = "";
446	  if (calmMode()) return;
447	  for (let i = 0; i < 30; i++) {
448	    const bit = document.createElement("span");
449	    bit.className = "confetti-bit";
450	    bit.style.left = `${Math.random() * 100}%`;
451	    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
452	    bit.style.setProperty("--dx", `${(Math.random() - 0.5) * 240}px`);
453	    bit.style.setProperty("--rot", `${Math.random() * 900 - 450}deg`);
454	    bit.style.animationDelay = `${Math.random() * 0.35}s`;
455	    bit.style.animationDuration = `${1.5 + Math.random()}s`;
456	    if (i % 3 === 0) bit.style.borderRadius = "50%";
457	    layer.appendChild(bit);
458	  }
459	  setTimeout(() => { layer.innerHTML = ""; }, 3200);
460	}
461	
462	function revealBadge(isMaster) {
463	  const [icon, ...name] = BADGES[mode].split(" ");
464	  $("badge-art").textContent = icon;
465	  $("badge-name").textContent = name.join(" ");
466	  $("badge-reveal").classList.remove("hidden");
467	  replayAnimation($("badge-art"));
468	  replayAnimation($("badge-name"));
469	
470	  if (isMaster) {
471	    $("badge-master").textContent = "🏆 PhishSense Master: all three badges earned!";
472	    $("badge-master").classList.remove("hidden");
473	    replayAnimation($("badge-master"));
474	  } else {
475	    $("badge-master").classList.add("hidden");
476	  }
477	  burstConfetti();
478	}
479	
480	// ---------- End of run ----------
481	function renderRecap() {
482	  // Group the same red flag together so repeats show as a count.
483	  const groups = new Map();
484	  missed.forEach((flag) => {
485	    const key = flag.toLowerCase().replace(/\s+/g, " ");
486	    const hit = groups.get(key);
487	    if (hit) hit.n++;
488	    else groups.set(key, { text: flag, n: 1 });
489	  });
490	  const items = [...groups.values()].sort((a, b) => b.n - a.n);
491	
492	  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
493	    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
494	    : `<p class="clean">You caught every red flag!</p>`);
495	  $("recap").classList.remove("hidden");
496	}
497	
498	async function finish() {
499	  const passed = correct >= TO_PASS;
500	  const badge = passed ? mode : null;
501	  const player = await apiSaveScore($("username").value.trim(), correct * PER_CORRECT, badge);
502	
503	  const owned = Array.isArray(player?.badges) ? player.badges : (passed ? [mode] : []);
504	  const isMaster = ALL_MODES.every((m) => owned.includes(m));
505	
506	  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
