21	header { text-align: center; padding: 32px 16px 8px; }
22	header h1 { margin: 0; font-size: 44px; font-weight: 800; }
23	header h1 span { color: var(--teal); }
24	.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
25	.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }
26	
27	main { max-width: 640px; margin: 0 auto; padding: 16px; }
28	.hidden { display: none !important; }
29	
30	/* Start screen */
31	.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
32	.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
33	.step-label + input { margin-top: 0; }
34	
35	/* Mission screen */
36	.briefing { margin-top: 8px; line-height: 1.6; color: var(--muted); }
37	.briefing p { margin: 0 0 10px; }
38	.briefing p:last-child { margin-bottom: 0; }
39	.briefing b { color: var(--text); }
40	.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
41	.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
42	.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
43	.mission-buttons { display: flex; justify-content: space-between; gap: 12px; }
44	button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }
45	
46	input {
47	  display: block; width: 100%; margin: 0; padding: 12px;
48	  border-radius: 10px; border: 1px solid var(--navy-2);
49	  background: var(--navy-2); color: var(--text); font-size: 16px;
50	}
51	
52	button {
53	  font-family: inherit; font-size: 16px; font-weight: 600; cursor: pointer;
54	  border: none; border-radius: 10px; padding: 12px 18px;
55	  background: var(--teal); color: var(--navy);
56	}
57	button:disabled { opacity: 0.5; cursor: default; }
58	
59	.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
60	.mode { padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--teal); }
61	.mode small { color: var(--muted); font-weight: 400; }
62	
63	.card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
64	.card.good { border-left: 6px solid var(--green); }
65	.card.bad { border-left: 6px solid var(--red); }
66	
67	#progress { text-align: center; color: var(--muted); }
68	.loading { color: var(--muted); text-align: center; }
69	
70	/* ---------- Run status: progress dots + streak ---------- */
71	.run-bar {
72	  display: flex; align-items: center; justify-content: space-between;
73	  gap: 12px; min-height: 26px; margin-top: 4px;
74	}
75	.dots { display: flex; gap: 8px; }
76	.dot {
77	  width: 14px; height: 14px; border-radius: 50%;
78	  background: transparent; border: 2px solid #2b4a68;
79	  transition: background 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
80	}
81	.dot.current { border-color: var(--teal); transform: scale(1.2); }
82	.dot.correct { background: var(--green); border-color: var(--green); animation: dot-pop 0.4s ease; }
83	.dot.wrong { background: var(--red); border-color: var(--red); animation: dot-pop 0.4s ease; }
84	
85	.streak { margin: 0; font-size: 14px; font-weight: 600; color: var(--teal); white-space: nowrap; }
86	.run-bar { flex-wrap: wrap; row-gap: 8px; }
87	.run-right { display: flex; align-items: center; gap: 10px; margin-left: auto; }
88	
89	/* ---------- Trusted contacts (briefing card + play panel) ---------- */
90	.contacts-toggle {
91	  font-size: 13px; padding: 6px 12px; border-radius: 999px; white-space: nowrap;
92	  background: transparent; color: var(--text); border: 2px solid var(--navy-2);
93	}
94	.contacts-toggle:hover, .contacts-toggle.open { border-color: var(--teal); }
95	.contacts-toggle.open { background: rgba(45, 224, 196, 0.12); }
96	
97	.contacts-title {
98	  margin: 0 0 10px; font-size: 13px; font-weight: 600;
99	  letter-spacing: 2px; text-transform: uppercase; color: var(--teal);
100	}
101	.contacts-panel { margin: 12px 0 4px; border: 1px solid #2b4a68; }
102	.contacts-table { width: 100%; border-collapse: collapse; font-size: 14px; }
103	.contacts-table th, .contacts-table td {
104	  text-align: left; vertical-align: top; padding: 8px 6px;
105	  border-bottom: 1px solid rgba(159, 183, 201, 0.18);
106	}
107	.contacts-table thead th {
108	  padding-top: 0; font-size: 12px; font-weight: 600; color: var(--muted);
109	}
110	.contacts-table tbody th { font-weight: 600; color: var(--text); }
111	.contacts-table tbody th small { display: block; font-weight: 400; font-size: 12px; color: var(--muted); }
112	.contact-domain, .contact-phone { display: block; font-family: monospace; font-size: 14px; color: var(--teal); overflow-wrap: anywhere; }
113	.contact-phone { color: var(--text); }
114	.contacts-tip { margin: 10px 0 0; font-size: 13px; color: var(--muted); }
115	
116	/* ---------- Message area: glow, shake, floating score ---------- */
117	.message-wrap { position: relative; }
118	.pop-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
119	.pop-score {
120	  position: absolute; left: 50%; top: 24%;
121	  font-size: 40px; font-weight: 800; color: var(--green);
122	  text-shadow: 0 2px 12px rgba(10, 26, 51, 0.8);
123	  animation: float-up 1.3s ease-out forwards;
124	}
125	
126	#message.is-correct .email,
127	#message.is-correct .sms { animation: glow-green 1.1s ease-out; }
128	#message.is-wrong { animation: shake 0.45s ease-in-out; }
129	
130	@keyframes dot-pop {
131	  0% { transform: scale(0.6); }
132	  60% { transform: scale(1.35); }
133	  100% { transform: scale(1); }
134	}
135	@keyframes float-up {
136	  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.8); }
137	  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
138	  100% { opacity: 0; transform: translate(-50%, -96px) scale(1); }
139	}
140	@keyframes glow-green {
141	  0% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
142	  28% { box-shadow: 0 0 0 4px var(--green), 0 0 38px 10px rgba(61, 220, 132, 0.55); }
143	  100% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
144	}
145	@keyframes shake {
146	  10%, 90% { transform: translateX(-3px); }
147	  20%, 80% { transform: translateX(5px); }
148	  30%, 50%, 70% { transform: translateX(-9px); }
149	  40%, 60% { transform: translateX(9px); }
150	}
151	
152	/* ---------- Email: looks like an inbox message ---------- */
153	#message.card { padding: 0; background: none; }
154	.email {
155	  background: #f7f9fb; color: #1b2a3a;
156	  border-radius: 14px; overflow: hidden;
157	  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
158	}
159	.email::before {
160	  content: "INBOX";
161	  display: block; padding: 10px 18px;
162	  background: #dfe7ee; color: #45566a;
163	  font-size: 13px; font-weight: 600; letter-spacing: 1px;
164	}
165	.email-head {
166	  display: flex; align-items: flex-start; gap: 12px;
167	  padding: 14px 16px; border-bottom: 1px solid #e3e9ef;
168	}
169	.avatar {
170	  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
171	  background: var(--navy-2); color: #fff;
172	  display: flex; align-items: center; justify-content: center;
173	  font-size: 18px; font-weight: 800;
174	}
175	.email-who { flex: 1 1 auto; min-width: 0; }
176	.email-who .from { margin: 0; font-size: 14px; color: #5b6b7b; overflow-wrap: anywhere; }
177	.email-who .from b { color: #1b2a3a; }
178	.email-who .subject { margin: 3px 0 0; font-size: 15px; font-weight: 600; color: #1b2a3a; overflow-wrap: anywhere; }
179	.email-time { flex: 0 0 auto; margin: 2px 0 0; font-size: 12px; color: #7b8a99; white-space: nowrap; }
180	
181	.email .body { margin: 0; padding: 18px; line-height: 1.6; }
182	
183	.email-actions {
184	  display: flex; gap: 10px;
185	  padding: 12px 16px; border-top: 1px solid #e3e9ef; background: #eef3f7;
186	}
187	.email-actions button,
188	.email-actions button:disabled {
189	  font-size: 14px; padding: 8px 16px; border-radius: 8px;
190	  background: #e1e8ee; color: #9aa8b5; border: 1px solid #d3dce4;
191	  opacity: 1; cursor: not-allowed;
192	}
193	
194	/* ---------- Text message: looks like a phone ---------- */
195	.sms {
196	  width: 320px; max-width: 100%; margin: 0 auto; padding: 14px 16px 28px;
197	  background: #101826; border: 3px solid #2b3a4f; border-radius: 36px;
198	  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
199	}
200	.sms::before {
201	  content: ""; display: block; width: 90px; height: 6px;
202	  margin: 0 auto 12px; background: #2b3a4f; border-radius: 3px;
203	}
204	
205	/* Phone status bar: time, signal bars, battery */
206	.status-bar {
207	  display: flex; align-items: center; justify-content: space-between;
208	  padding: 0 4px 14px; font-size: 13px; font-weight: 600; color: var(--text);
209	}
210	.sb-right { display: flex; align-items: center; gap: 7px; }
211	.signal { display: flex; align-items: flex-end; gap: 2px; height: 11px; }
212	.signal i { width: 3px; background: var(--text); border-radius: 1px; }
213	.signal i:nth-child(1) { height: 4px; }
214	.signal i:nth-child(2) { height: 6px; }
215	.signal i:nth-child(3) { height: 9px; }
216	.signal i:nth-child(4) { height: 11px; }
217	.battery {
218	  position: relative; width: 25px; height: 13px;
219	  border: 1.5px solid var(--text); border-radius: 3px; padding: 2px;
220	}
221	.battery::after {
222	  content: ""; position: absolute; right: -4px; top: 3.5px;
223	  width: 2px; height: 5px; background: var(--text); border-radius: 0 2px 2px 0;
224	}
225	.bat-fill { display: block; height: 100%; width: 72%; background: var(--green); border-radius: 1px; }
226	
227	.sms .label { text-align: center; font-size: 13px; color: var(--muted); margin: 0 0 14px; }
228	.sms .label b { display: block; font-size: 16px; color: var(--text); }
229	.bubble {
230	  background: #e9edf2; color: #1b2a3a;
231	  padding: 12px 14px; border-radius: 18px 18px 18px 4px;
232	  line-height: 1.5; margin: 0; max-width: 85%;
233	}
234	
235	/* Links are buttons on purpose: they only preview, never open anything */
236	.link {
237	  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px;
238	  margin: 0; padding: 0 18px 18px;
239	}
240	.link-chip,
241	.link-chip:hover {
242	  font: inherit; font-weight: 600; text-align: left;
243	  padding: 0; margin: 0; border: 0; border-radius: 3px;
244	  background: none; color: #1a5fd0;
245	  text-decoration: underline; text-underline-offset: 3px;
246	  cursor: help; transform: none; box-shadow: none;
247	  overflow-wrap: anywhere;
248	}
249	.link-chip:focus-visible { outline: 2px solid #1a5fd0; outline-offset: 3px; }
250	.link-hint {
251	  font-size: 12px; font-weight: 600; color: #7b8a99;
252	  padding: 2px 8px; border-radius: 999px; background: #e7edf2;
253	}
254	.hint-tap { display: none; }
255	@media (hover: none) {
256	  .hint-hover { display: none; }
257	  .hint-tap { display: inline; }
258	}
259	.sms .link { padding: 10px 0 0; }
260	.sms .link-chip { font-family: monospace; font-weight: 400; color: var(--teal); }
261	.sms .link-chip:focus-visible { outline-color: var(--teal); }
262	.sms .link-hint { background: #1d2a3d; color: var(--muted); }
263	
264	/* The popup that shows a link's real destination */
265	.link-peek {
266	  position: fixed; z-index: 1000;
267	  width: max-content; max-width: min(360px, calc(100vw - 24px));
268	  padding: 10px 12px; border-radius: 10px;
269	  background: #0d1b2e; color: var(--text);
270	  border: 1px solid #2b3a4f;
271	  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
272	  font-size: 13px; line-height: 1.45;
273	  animation: peek-in 0.12s ease-out;
274	}
275	.link-peek p { margin: 0; }
276	.peek-title { color: var(--muted); font-weight: 600; margin-bottom: 4px !important; }
277	.peek-url { font-family: monospace; font-size: 14px; overflow-wrap: anywhere; color: #c9d6e2; }
278	.peek-sub { color: inherit; }
279	.peek-domain { color: #ffd166; background: rgba(255, 209, 102, 0.12); padding: 0 2px; border-radius: 3px; }
280	.peek-tip { margin-top: 6px !important; color: var(--muted); font-size: 12px; }
281	.peek-tip b { color: var(--text); }
282	@keyframes peek-in {
283	  from { opacity: 0; transform: translateY(4px); }
284	}
285	.link-reveal { margin-bottom: 0; }
286	
287	.answers { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
288	.answer.phish { background: var(--red); color: white; }
289	.answer.legit { background: var(--green); color: var(--navy); }
290	
291	#btn-next, #btn-home { display: block; margin: 0 auto; }
292	#end-screen { text-align: center; }
293	
294	/* ---------- Badge reveal ---------- */
295	.badge-reveal { position: relative; padding: 10px 0 2px; }
296	.badge-art {
297	  font-size: 96px; line-height: 1.1;
298	  animation: badge-drop 1.1s cubic-bezier(0.2, 0.75, 0.3, 1) both;
299	}
300	.badge-name {
301	  margin: 2px 0 0; font-size: 26px; font-weight: 800; color: var(--teal);
302	  animation: fade-rise 0.5s ease-out 0.75s both;
303	}
304	.badge-master {
305	  display: inline-block; margin: 14px 0 0; padding: 8px 16px;
306	  border: 2px solid var(--teal); border-radius: 999px;
307	  background: rgba(45, 224, 196, 0.1);
308	  font-weight: 700; color: var(--text);
309	  animation: fade-rise 0.5s ease-out 1.1s both;
310	}
311	
312	@keyframes badge-drop {
313	  0% { opacity: 0; transform: translateY(-170px) scale(0.4) rotate(0deg); }
314	  55% { opacity: 1; transform: translateY(0) scale(1.28) rotate(360deg); }
315	  70% { transform: translateY(0) scale(0.92) rotate(372deg); }
316	  85% { transform: translateY(0) scale(1.07) rotate(354deg); }
317	  100% { opacity: 1; transform: translateY(0) scale(1) rotate(360deg); }
318	}
319	@keyframes fade-rise {
320	  0% { opacity: 0; transform: translateY(12px); }
321	  100% { opacity: 1; transform: translateY(0); }
322	}
323	
324	/* Confetti burst (pure CSS/JS, no libraries) */
325	.confetti { position: absolute; left: 0; right: 0; top: 0; height: 0; pointer-events: none; }
326	.confetti-bit {
327	  position: absolute; top: 0; width: 9px; height: 14px; border-radius: 2px;
328	  animation-name: confetti-fall; animation-timing-function: ease-in; animation-fill-mode: forwards;
329	}
330	@keyframes confetti-fall {
331	  0% { opacity: 1; transform: translate(0, -10px) rotate(0deg); }
332	  100% { opacity: 0; transform: translate(var(--dx), 300px) rotate(var(--rot)); }
333	}
334	
335	/* ---------- End of run recap ---------- */
336	.recap { text-align: left; }
337	.recap h3 { margin: 0 0 10px; font-size: 16px; color: var(--text); }
338	.recap ul { margin: 0; padding-left: 20px; }
339	.recap li { margin: 7px 0; color: var(--muted); line-height: 1.45; }
340	.recap .count { color: var(--teal); font-weight: 700; }
341	.recap .clean { margin: 0; font-weight: 600; color: var(--green); }
342	
343	.leaderboard h3 { margin-top: 0; }
344	.leaderboard li { margin: 6px 0; }
345	.leaderboard span { float: right; color: var(--muted); }
346	.leaderboard .empty { color: var(--muted); list-style: none; margin-left: -20px; }
347	
348	/* ---------- Phone-sized screens ---------- */
349	@media (max-width: 430px) {
350	  header { padding: 20px 14px 6px; }
351	  header h1 { font-size: 34px; }
352	  .logo { width: 92px; }
353	  main { padding: 12px; }
354	
355	  .mode { padding: 14px 4px; font-size: 14px; }
356	  .mode small { font-size: 11px; }
357	  .mission-buttons { flex-direction: column; }
358	  .mission-buttons button { width: 100%; }
359	
360	  .dot { width: 12px; height: 12px; }
361	  .streak { font-size: 13px; }
362	  .dots { gap: 6px; }
363	  .run-right { gap: 6px; }
364	  .contacts-toggle { font-size: 12px; padding: 5px 9px; }
365	  .contacts-table { font-size: 13px; }
366	  .pop-score { font-size: 34px; }
367	
368	  .email-head { padding: 12px; gap: 10px; }
369	  .avatar { width: 36px; height: 36px; font-size: 16px; }
370	  .email-who .subject { font-size: 14px; }
371	  .email .body { padding: 14px; }
372	  .link { padding: 0 14px 14px; }
373	  .email-actions { padding: 10px 12px; }
374	  .email-actions button, .email-actions button:disabled { padding: 7px 12px; font-size: 13px; }
375	
376	  .badge-art { font-size: 74px; }
377	  .badge-name { font-size: 22px; }
378	}
379	
380	/* ---------- Respect reduced motion ---------- */
381	@media (prefers-reduced-motion: reduce) {
382	  *, *::before, *::after {
383	    animation-duration: 0.001ms !important;
384	    animation-delay: 0ms !important;
385	    animation-iteration-count: 1 !important;
386	    transition-duration: 0.001ms !important;
387	  }
388	  #message.is-correct .email,
389	  #message.is-correct .sms { animation: none; box-shadow: 0 0 0 4px var(--green), 0 10px 30px rgba(0, 0, 0, 0.35); }
390	  #message.is-wrong { animation: none; }
391	  #message.is-wrong .email,
392	  #message.is-wrong .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
393	  .dot.correct, .dot.wrong { animation: none; }
394	}
395	
396	/* ---------- Fish cursor (home screen only, see fish-cursor.js) ---------- */
397	body.fish-mode, body.fish-mode * { cursor: none !important; }
398	.fish-cursor {
399	  position: fixed; left: 0; top: 0; z-index: 9999;
400	  width: 50px; height: 36px; pointer-events: none;
401	  transform-origin: 46px 18px; opacity: 0;
402	  transition: opacity 0.2s ease;
403	  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.35));
404	}
405	.fish-cursor svg { display: block; overflow: visible; }
406	.fish-tail {
407	  transform-origin: 14px 18px;
408	  animation: fish-wag var(--wag, 0.6s) ease-in-out infinite alternate;
409	}
410	.fish-cursor.gulp svg { animation: fish-gulp 0.3s ease; }
411	@keyframes fish-wag {
412	  from { transform: rotate(-16deg); }
413	  to   { transform: rotate(16deg); }
414	}
415	@keyframes fish-gulp {
416	  40% { transform: scale(1.25, 0.85); }
417	}
418	.fish-bubble {
419	  position: fixed; z-index: 9998; pointer-events: none;
420	  border-radius: 50%; border: 1.5px solid rgba(185, 255, 241, 0.75);
421	  background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6), rgba(45, 224, 196, 0.08) 60%);
422	  transform: translate(-50%, -50%);
423	  animation: bubble-rise 1.2s ease-out forwards;
424	}
425	.fish-bubble.burst { animation-duration: 0.8s; }
426	@keyframes bubble-rise {
427	  from { opacity: 0.9; transform: translate(-50%, -50%) scale(0.6); }
428	  to   { opacity: 0; transform: translate(calc(-50% + var(--drift)), calc(-50% - 60px)) scale(1.1); }
429	}
430

file.content:
/* PhishSense colors: navy + teal, matching the logo */
:root {
  --navy: #0a1a33;
  --navy-2: #123a5c;
  --teal: #2de0c4;
  --text: #e9f1f7;
  --muted: #9fb7c9;
  --red: #ff5d6c;
  --green: #3ddc84;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Inter", Arial, sans-serif;
  background: var(--navy);
  color: var(--text);
}

header { text-align: center; padding: 32px 16px 8px; }
header h1 { margin: 0; font-size: 44px; font-weight: 800; }
header h1 span { color: var(--teal); }
.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }

main { max-width: 640px; margin: 0 auto; padding: 16px; }
.hidden { display: none !important; }

/* Start screen */
.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
.step-label + input { margin-top: 0; }

/* Mission screen */
.briefing { margin-top: 8px; line-height: 1.6; color: var(--muted); }
.briefing p { margin: 0 0 10px; }
.briefing p:last-child { margin-bottom: 0; }
.briefing b { color: var(--text); }
.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
.mission-buttons { display: flex; justify-content: space-between; gap: 12px; }
button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }

input {
  display: block; width: 100%; margin: 0; padding: 12px;
  border-radius: 10px; border: 1px solid var(--navy-2);
  background: var(--navy-2); color: var(--text); font-size: 16px;
}

button {
  font-family: inherit; font-size: 16px; font-weight: 600; cursor: pointer;
  border: none; border-radius: 10px; padding: 12px 18px;
  background: var(--teal); color: var(--navy);
}
button:disabled { opacity: 0.5; cursor: default; }

.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mode { padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--teal); }
.mode small { color: var(--muted); font-weight: 400; }

.card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
.card.good { border-left: 6px solid var(--green); }
.card.bad { border-left: 6px solid var(--red); }

#progress { text-align: center; color: var(--muted); }
.loading { color: var(--muted); text-align: center; }

/* ---------- Run status: progress dots + streak ---------- */
.run-bar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; min-height: 26px; margin-top: 4px;
}
.dots { display: flex; gap: 8px; }
.dot {
  width: 14px; height: 14px; border-radius: 50%;
  background: transparent; border: 2px solid #2b4a68;
  transition: background 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
}
.dot.current { border-color: var(--teal); transform: scale(1.2); }
.dot.correct { background: var(--green); border-color: var(--green); animation: dot-pop 0.4s ease; }
.dot.wrong { background: var(--red); border-color: var(--red); animation: dot-pop 0.4s ease; }

.streak { margin: 0; font-size: 14px; font-weight: 600; color: var(--teal); white-space: nowrap; }
.run-bar { flex-wrap: wrap; row-gap: 8px; }
.run-right { display: flex; align-items: center; gap: 10px; margin-left: auto; }

/* ---------- Trusted contacts (briefing card + play panel) ---------- */
.contacts-toggle {
  font-size: 13px; padding: 6px 12px; border-radius: 999px; white-space: nowrap;
  background: transparent; color: var(--text); border: 2px solid var(--navy-2);
}
.contacts-toggle:hover, .contacts-toggle.open { border-color: var(--teal); }
.contacts-toggle.open { background: rgba(45, 224, 196, 0.12); }

.contacts-title {
  margin: 0 0 10px; font-size: 13px; font-weight: 600;
  letter-spacing: 2px; text-transform: uppercase; color: var(--teal);
}
.contacts-panel { margin: 12px 0 4px; border: 1px solid #2b4a68; }
.contacts-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.contacts-table th, .contacts-table td {
  text-align: left; vertical-align: top; padding: 8px 6px;
  border-bottom: 1px solid rgba(159, 183, 201, 0.18);
}
.contacts-table thead th {
  padding-top: 0; font-size: 12px; font-weight: 600; color: var(--muted);
}
.contacts-table tbody th { font-weight: 600; color: var(--text); }
.contacts-table tbody th small { display: block; font-weight: 400; font-size: 12px; color: var(--muted); }
.contact-domain, .contact-phone { display: block; font-family: monospace; font-size: 14px; color: var(--teal); overflow-wrap: anywhere; }
.contact-phone { color: var(--text); }
.contacts-tip { margin: 10px 0 0; font-size: 13px; color: var(--muted); }

/* ---------- Message area: glow, shake, floating score ---------- */
.message-wrap { position: relative; }
.pop-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
.pop-score {
  position: absolute; left: 50%; top: 24%;
  font-size: 40px; font-weight: 800; color: var(--green);
  text-shadow: 0 2px 12px rgba(10, 26, 51, 0.8);
  animation: float-up 1.3s ease-out forwards;
}

#message.is-correct .email,
#message.is-correct .sms { animation: glow-green 1.1s ease-out; }
#message.is-wrong { animation: shake 0.45s ease-in-out; }

@keyframes dot-pop {
  0% { transform: scale(0.6); }
  60% { transform: scale(1.35); }
  100% { transform: scale(1); }
}
@keyframes float-up {
  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.8); }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -96px) scale(1); }
}
@keyframes glow-green {
  0% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
  28% { box-shadow: 0 0 0 4px var(--green), 0 0 38px 10px rgba(61, 220, 132, 0.55); }
  100% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
}
@keyframes shake {
  10%, 90% { transform: translateX(-3px); }
  20%, 80% { transform: translateX(5px); }
  30%, 50%, 70% { transform: translateX(-9px); }
  40%, 60% { transform: translateX(9px); }
}

/* ---------- Email: looks like an inbox message ---------- */
#message.card { padding: 0; background: none; }
.email {
  background: #f7f9fb; color: #1b2a3a;
  border-radius: 14px; overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
.email::before {
  content: "INBOX";
  display: block; padding: 10px 18px;
  background: #dfe7ee; color: #45566a;
  font-size: 13px; font-weight: 600; letter-spacing: 1px;
}
.email-head {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 14px 16px; border-bottom: 1px solid #e3e9ef;
}
.avatar {
  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
  background: var(--navy-2); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 800;
}
.email-who { flex: 1 1 auto; min-width: 0; }
.email-who .from { margin: 0; font-size: 14px; color: #5b6b7b; overflow-wrap: anywhere; }
.email-who .from b { color: #1b2a3a; }
.email-who .subject { margin: 3px 0 0; font-size: 15px; font-weight: 600; color: #1b2a3a; overflow-wrap: anywhere; }
.email-time { flex: 0 0 auto; margin: 2px 0 0; font-size: 12px; color: #7b8a99; white-space: nowrap; }

.email .body { margin: 0; padding: 18px; line-height: 1.6; }

.email-actions {
  display: flex; gap: 10px;
  padding: 12px 16px; border-top: 1px solid #e3e9ef; background: #eef3f7;
}
.email-actions button,
.email-actions button:disabled {
  font-size: 14px; padding: 8px 16px; border-radius: 8px;
  background: #e1e8ee; color: #9aa8b5; border: 1px solid #d3dce4;
  opacity: 1; cursor: not-allowed;
}

/* ---------- Text message: looks like a phone ---------- */
.sms {
  width: 320px; max-width: 100%; margin: 0 auto; padding: 14px 16px 28px;
  background: #101826; border: 3px solid #2b3a4f; border-radius: 36px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
.sms::before {
  content: ""; display: block; width: 90px; height: 6px;
  margin: 0 auto 12px; background: #2b3a4f; border-radius: 3px;
}

/* Phone status bar: time, signal bars, battery */
.status-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 4px 14px; font-size: 13px; font-weight: 600; color: var(--text);
}
.sb-right { display: flex; align-items: center; gap: 7px; }
.signal { display: flex; align-items: flex-end; gap: 2px; height: 11px; }
.signal i { width: 3px; background: var(--text); border-radius: 1px; }
.signal i:nth-child(1) { height: 4px; }
.signal i:nth-child(2) { height: 6px; }
.signal i:nth-child(3) { height: 9px; }
.signal i:nth-child(4) { height: 11px; }
.battery {
  position: relative; width: 25px; height: 13px;
  border: 1.5px solid var(--text); border-radius: 3px; padding: 2px;
}
.battery::after {
  content: ""; position: absolute; right: -4px; top: 3.5px;
  width: 2px; height: 5px; background: var(--text); border-radius: 0 2px 2px 0;
}
.bat-fill { display: block; height: 100%; width: 72%; background: var(--green); border-radius: 1px; }

.sms .label { text-align: center; font-size: 13px; color: var(--muted); margin: 0 0 14px; }
.sms .label b { display: block; font-size: 16px; color: var(--text); }
.bubble {
  background: #e9edf2; color: #1b2a3a;
  padding: 12px 14px; border-radius: 18px 18px 18px 4px;
  line-height: 1.5; margin: 0; max-width: 85%;
}

/* Links are buttons on purpose: they only preview, never open anything */
.link {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px;
  margin: 0; padding: 0 18px 18px;
}
.link-chip,
.link-chip:hover {
  font: inherit; font-weight: 600; text-align: left;
  padding: 0; margin: 0; border: 0; border-radius: 3px;
  background: none; color: #1a5fd0;
  text-decoration: underline; text-underline-offset: 3px;
  cursor: help; transform: none; box-shadow: none;
  overflow-wrap: anywhere;
}
.link-chip:focus-visible { outline: 2px solid #1a5fd0; outline-offset: 3px; }
.link-hint {
  font-size: 12px; font-weight: 600; color: #7b8a99;
  padding: 2px 8px; border-radius: 999px; background: #e7edf2;
}
.hint-tap { display: none; }
@media (hover: none) {
  .hint-hover { display: none; }
  .hint-tap { display: inline; }
}
.sms .link { padding: 10px 0 0; }
.sms .link-chip { font-family: monospace; font-weight: 400; color: var(--teal); }
.sms .link-chip:focus-visible { outline-color: var(--teal); }
.sms .link-hint { background: #1d2a3d; color: var(--muted); }

/* The popup that shows a link's real destination */
.link-peek {
  position: fixed; z-index: 1000;
  width: max-content; max-width: min(360px, calc(100vw - 24px));
  padding: 10px 12px; border-radius: 10px;
  background: #0d1b2e; color: var(--text);
  border: 1px solid #2b3a4f;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
  font-size: 13px; line-height: 1.45;
  animation: peek-in 0.12s ease-out;
}
.link-peek p { margin: 0; }
.peek-title { color: var(--muted); font-weight: 600; margin-bottom: 4px !important; }
.peek-url { font-family: monospace; font-size: 14px; overflow-wrap: anywhere; color: #c9d6e2; }
.peek-sub { color: inherit; }
.peek-domain { color: #ffd166; background: rgba(255, 209, 102, 0.12); padding: 0 2px; border-radius: 3px; }
.peek-tip { margin-top: 6px !important; color: var(--muted); font-size: 12px; }
.peek-tip b { color: var(--text); }
@keyframes peek-in {
  from { opacity: 0; transform: translateY(4px); }
}
.link-reveal { margin-bottom: 0; }

.answers { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.answer.phish { background: var(--red); color: white; }
.answer.legit { background: var(--green); color: var(--navy); }

#btn-next, #btn-home { display: block; margin: 0 auto; }
#end-screen { text-align: center; }

/* ---------- Badge reveal ---------- */
.badge-reveal { position: relative; padding: 10px 0 2px; }
.badge-art {
  font-size: 96px; line-height: 1.1;
  animation: badge-drop 1.1s cubic-bezier(0.2, 0.75, 0.3, 1) both;
}
.badge-name {
  margin: 2px 0 0; font-size: 26px; font-weight: 800; color: var(--teal);
  animation: fade-rise 0.5s ease-out 0.75s both;
}
.badge-master {
  display: inline-block; margin: 14px 0 0; padding: 8px 16px;
  border: 2px solid var(--teal); border-radius: 999px;
  background: rgba(45, 224, 196, 0.1);
  font-weight: 700; color: var(--text);
  animation: fade-rise 0.5s ease-out 1.1s both;
}

@keyframes badge-drop {
  0% { opacity: 0; transform: translateY(-170px) scale(0.4) rotate(0deg); }
  55% { opacity: 1; transform: translateY(0) scale(1.28) rotate(360deg); }
  70% { transform: translateY(0) scale(0.92) rotate(372deg); }
  85% { transform: translateY(0) scale(1.07) rotate(354deg); }
  100% { opacity: 1; transform: translateY(0) scale(1) rotate(360deg); }
}
@keyframes fade-rise {
  0% { opacity: 0; transform: translateY(12px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* Confetti burst (pure CSS/JS, no libraries) */
.confetti { position: absolute; left: 0; right: 0; top: 0; height: 0; pointer-events: none; }
.confetti-bit {
  position: absolute; top: 0; width: 9px; height: 14px; border-radius: 2px;
  animation-name: confetti-fall; animation-timing-function: ease-in; animation-fill-mode: forwards;
}
@keyframes confetti-fall {
  0% { opacity: 1; transform: translate(0, -10px) rotate(0deg); }
  100% { opacity: 0; transform: translate(var(--dx), 300px) rotate(var(--rot)); }
}

/* ---------- End of run recap ---------- */
.recap { text-align: left; }
.recap h3 { margin: 0 0 10px; font-size: 16px; color: var(--text); }
.recap ul { margin: 0; padding-left: 20px; }
.recap li { margin: 7px 0; color: var(--muted); line-height: 1.45; }
.recap .count { color: var(--teal); font-weight: 700; }
.recap .clean { margin: 0; font-weight: 600; color: var(--green); }

.leaderboard h3 { margin-top: 0; }
.leaderboard li { margin: 6px 0; }
.leaderboard span { float: right; color: var(--muted); }
.leaderboard .empty { color: var(--muted); list-style: none; margin-left: -20px; }

/* ---------- Phone-sized screens ---------- */
@media (max-width: 430px) {
  header { padding: 20px 14px 6px; }
  header h1 { font-size: 34px; }
  .logo { width: 92px; }
  main { padding: 12px; }

  .mode { padding: 14px 4px; font-size: 14px; }
  .mode small { font-size: 11px; }
  .mission-buttons { flex-direction: column; }
  .mission-buttons button { width: 100%; }

  .dot { width: 12px; height: 12px; }
  .streak { font-size: 13px; }
  .dots { gap: 6px; }
  .run-right { gap: 6px; }
  .contacts-toggle { font-size: 12px; padding: 5px 9px; }
  .contacts-table { font-size: 13px; }
  .pop-score { font-size: 34px; }

  .email-head { padding: 12px; gap: 10px; }
  .avatar { width: 36px; height: 36px; font-size: 16px; }
  .email-who .subject { font-size: 14px; }
  .email .body { padding: 14px; }
  .link { padding: 0 14px 14px; }
  .email-actions { padding: 10px 12px; }
  .email-actions button, .email-actions button:disabled { padding: 7px 12px; font-size: 13px; }

  .badge-art { font-size: 74px; }
  .badge-name { font-size: 22px; }
}

/* ---------- Respect reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  #message.is-correct .email,
  #message.is-correct .sms { animation: none; box-shadow: 0 0 0 4px var(--green), 0 10px 30px rgba(0, 0, 0, 0.35); }
  #message.is-wrong { animation: none; }
  #message.is-wrong .email,
  #message.is-wrong .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
  .dot.correct, .dot.wrong { animation: none; }
}

/* ---------- Fish cursor (home screen only, see fish-cursor.js) ---------- */
body.fish-mode, body.fish-mode * { cursor: none !important; }
.fish-cursor {
  position: fixed; left: 0; top: 0; z-index: 9999;
  width: 50px; height: 36px; pointer-events: none;
  transform-origin: 46px 18px; opacity: 0;
  transition: opacity 0.2s ease;
  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.35));
}
.fish-cursor svg { display: block; overflow: visible; }
.fish-tail {
  transform-origin: 14px 18px;
  animation: fish-wag var(--wag, 0.6s) ease-in-out infinite alternate;
}
.fish-cursor.gulp svg { animation: fish-gulp 0.3s ease; }
@keyframes fish-wag {
  from { transform: rotate(-16deg); }
  to   { transform: rotate(16deg); }
}
@keyframes fish-gulp {
  40% { transform: scale(1.25, 0.85); }
}
.fish-bubble {
  position: fixed; z-index: 9998; pointer-events: none;
  border-radius: 50%; border: 1.5px solid rgba(185, 255, 241, 0.75);
  background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6), rgba(45, 224, 196, 0.08) 60%);
  transform: translate(-50%, -50%);
  animation: bubble-rise 1.2s ease-out forwards;
}
.fish-bubble.burst { animation-duration: 0.8s; }
@keyframes bubble-rise {
  from { opacity: 0.9; transform: translate(-50%, -50%) scale(0.6); }
  to   { opacity: 0; transform: translate(calc(-50% + var(--drift)), calc(-50% - 60px)) scale(1.1); }
}

