/* ---------- Answer reactions ---------- */
/* Keeps a tilted card from adding a sideways scrollbar while the hook pulls it */
body { overflow-x: clip; }

#message.hook-anim { position: relative; z-index: 50; animation: none; }
#message.is-hooked .email,
#message.is-hooked .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
#message.is-cautious .email,
#message.is-cautious .sms { box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.6), 0 10px 30px rgba(0, 0, 0, 0.35); }

.hook-rig {
  position: absolute; z-index: 60; width: 0; height: 0;
  pointer-events: none; transform-origin: 0 0; will-change: transform;
}
.hook-line {
  position: absolute; left: -1px; top: 0;
  width: 2px; height: var(--drop);
  background: #dfe7ee; box-shadow: 0 0 0 1px rgba(10, 26, 51, 0.55);
}
.hook {
  position: absolute; left: -20px; top: calc(var(--drop) - 1px);
  overflow: visible; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.35));
}

.reaction {
  margin: 0 0 14px; padding: 12px 16px; border-radius: 12px;
  text-align: center; font-size: 20px; font-weight: 800; line-height: 1.3;
  animation: reaction-pop 0.35s cubic-bezier(0.2, 0.8, 0.3, 1.25) both;
}
.reaction.hooked {
  color: #ffc2c8; background: rgba(255, 93, 108, 0.14); border: 2px solid var(--red);
  animation-delay: 0.45s; /* appears as the hook bites */
}
.reaction.dodged {
  color: #b8f5d2; background: rgba(61, 220, 132, 0.12); border: 2px solid var(--green);
  animation-delay: 0.35s; /* appears as the card ducks */
}
.reaction.safe {
  color: #b8f5d2; background: rgba(61, 220, 132, 0.12); border: 2px solid var(--green);
}
/* Friendly, not harsh: soft amber, a gentle fade instead of a pop */
.reaction.cautious {
  color: #ffe3a3; background: rgba(255, 209, 102, 0.1);
  border: 2px solid rgba(255, 209, 102, 0.45);
  font-weight: 700; animation-name: reaction-soft; animation-duration: 0.4s;
}
.card.gentle { border-left: 6px solid #ffd166; }
.gentle-tip { margin-bottom: 0; color: #ffe3a3; }

@keyframes reaction-pop {
  0% { opacity: 0; transform: scale(0.85); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes reaction-soft {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

